<?php
use App\Models\Cms\MenuItem;
use Livewire\Attributes\Layout;
use Livewire\Volt\Component;
new #[Layout('layouts.app')] class extends Component {
    public ?int $editing=null,$parent_id=null;public string $label='',$url='';public int $sort_order=0;public bool $is_visible=true;
    public function edit(int $id): void {$item=MenuItem::findOrFail($id);$this->editing=$id;$this->fill($item->only(['label','url','parent_id','sort_order','is_visible']));}
    public function resetForm(): void {$this->reset(['editing','parent_id','label','url','sort_order']);$this->is_visible=true;$this->resetValidation();}
    public function save(): void {$data=$this->validate(['label'=>['required','string','max:255'],'url'=>['required','string','max:255'],'parent_id'=>['nullable','exists:cms_menu_items,id'],'sort_order'=>['integer'],'is_visible'=>['boolean']]);if($this->editing)$data['parent_id']===$this->editing?$data['parent_id']=null:null;$this->editing?MenuItem::findOrFail($this->editing)->update($data):MenuItem::create($data);$this->resetForm();session()->flash('success','Menu item saved.');}
    public function delete(int $id): void {MenuItem::findOrFail($id)->delete();if($this->editing===$id)$this->resetForm();}
    public function with(): array {return ['items'=>MenuItem::with('parent')->orderBy('sort_order')->get()];}
}; ?>
